#!/usr/bin/env bash
# Despliega la landing de MenuVibes al VPS. Pegar en hPanel -> VPS -> Browser Terminal.
# URL final: https://menu.rovicrm.com/landing.html
set -e
DIR=/var/www/menuvibes
mkdir -p "$DIR"

echo "" | base64 -d > "$DIR/landing.html"

chmod 644 "$DIR/landing.html"
echo "== Desplegado =="
ls -la "$DIR/landing.html"
echo ""
echo "URL: https://menu.rovicrm.com/landing.html"
